import math
def normalize(v):
    n = math.sqrt(sum(x * x for x in v))
    return [x / n for x in v]
query = normalize([1.0, 1.0, 0.0])
docs = {"charger": [2.0, 2.0, 0.1], "bottle": [0.0, 0.2, 3.0], "cable": [1.0, 0.5, 0.0]}
scores = {k: round(sum(a * b for a, b in zip(query, normalize(v))), 3) for k, v in docs.items()}
print(sorted(scores.items(), key=lambda kv: -kv[1]))
